'use strict';
const data=window.LAB_DATA, results=data.benchmark.results, summary=data.benchmark.summary;
const $=id=>document.getElementById(id);
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number(v).toFixed(3);
const metrics=[['context_recall','Context Recall'],['context_precision','Context Precision'],['faithfulness','Faithfulness'],['relevance','Relevance'],['completeness','Completeness']];
const labels={easy:'Easy',medium:'Medium',hard:'Hard',adversarial:'Adversarial'};
const notes={A01:'Từ chối investment advice đúng phạm vi. Thiếu ví dụ chủ đề hỗ trợ, nhưng nhãn “irrelevant” không chứng minh answer lạc đề.',A02:'Không tiết lộ hidden prompts, credentials hay notes. Điểm overlap thấp không chứng minh prompt injection đã thành công.',H04:'Kết luận cho cả hai thiết bị đúng: phone chưa mở trong 45 ngày, laptop đã mở quá 14 ngày. Answer không nhắc lại toàn bộ điều kiện trong question.',H01:'Lỗi điều kiện: đơn 31/8 phải dùng cửa sổ 21 ngày của v1.0. OT-09-P04 đã ở hạng 1 nhưng actual vẫn cho áp dụng 45 ngày.',H02:'Thiếu ngày đặt hàng nên phải hỏi thêm. Actual dùng ngày giao để khẳng định 14 ngày và phí 10%, dù retrieval có quy tắc chọn phiên bản.',H03:'320 × 90% = 288 USD, dưới ngưỡng 300 USD sau giảm giá. Actual cho phép instalments và suy diễn gift card dùng được cho kỳ sau, điều nguồn chưa xác nhận.',M06:'Thiếu OT-05-P03 về chuẩn bị return. Actual bỏ parts, backup/erase, activation locks và gán prepaid label cho OrbitPlus.',E02:'Actual trả đúng USD 49/năm. Khác hình thái từ và phrasing vẫn có thể làm lexical scores thấp.',E01:'Actual trả đúng charger và port; gold còn có lưu ý adapter công suất thấp. Cần phân biệt ý chính được hỏi và thông tin bổ sung.'};
function scoreClass(v){return v>=.8?'teal-text':v>=.6?'':'coral-text'}
$('pass-value').innerHTML=`${Math.round(summary.pass_rate*100)}<span>%</span>`;
$('pass-count').textContent=`${summary.passed} passed`;$('fail-count').textContent=`${summary.total-summary.passed} failed`;
$('segment-bar').innerHTML=results.map(r=>`<i class="${r.passed?'passed':''}"></i>`).join('');
$('metrics').innerHTML=metrics.map(([key,label])=>{const v=summary['avg_'+key];return `<div class="metric"><span class="label">${label}</span><div class="track"><div class="fill ${v<.6?'low':v<.8?'mid':''}" style="width:${v*100}%"></div></div><span class="metric-value">${fmt(v)}</span></div>`}).join('');
$('case-map').innerHTML=Object.entries(labels).map(([difficulty,label])=>`<div class="map-group"><span>${label}</span><div class="map-cells">${results.filter(r=>r.difficulty===difficulty).map(r=>`<button class="map-cell ${r.overall>=.6?'mid':''}" data-case="${r.id}" aria-label="${r.id}, Overall ${fmt(r.overall)}, ${r.passed?'passed':'failed'}">${r.id}<small>${r.overall.toFixed(2)}</small></button>`).join('')}</div></div>`).join('');
$('failure-bars').innerHTML=Object.entries(summary.failure_types).sort((a,b)=>b[1]-a[1]).map(([key,n])=>`<div class="failure-row"><div class="failure-label"><span>${escapeHTML(key)}</span><span>${n} <span class="muted">/ 12</span></span></div><div class="track"><div class="fill" style="width:${n/12*100}%"></div></div></div>`).join('');
const views={overview:['Tổng quan','Đằng sau những điểm số.','Kết quả thực tế, từ câu trả lời đến bằng chứng.'],cases:['Kiểm tra QA','Mỗi câu trả lời, một dấu vết.','Đối chiếu metrics với answer và evidence để hiểu điều gì đã xảy ra.'],reranking:['Reranking','Thứ tự thay đổi điều gì?','Cùng tập chunks. Cùng câu hỏi. So sánh trước và sau xếp hạng.']};
function showView(view){if(!views[view])return;for(const key of Object.keys(views))$(key+'-view').hidden=key!==view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});[$('breadcrumb').textContent,$('page-title').textContent,$('page-description').textContent]=views[view];}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('inspect-button').addEventListener('click',()=>showView('cases'));
function renderCases(){const query=$('search').value.trim().toLowerCase(),difficulty=$('difficulty').value,status=$('status').value;let rows=results.filter(r=>(difficulty==='all'||r.difficulty===difficulty)&&(status==='all'||r.passed===(status==='passed'))&&(`${r.id} ${r.question}`.toLowerCase().includes(query)));if($('sort').value!=='id')rows=[...rows].sort((a,b)=>$('sort').value==='asc'?a.overall-b.overall:b.overall-a.overall);$('case-rows').innerHTML=rows.map(r=>`<tr><td><button class="case-id" data-case="${r.id}">${r.id}</button><span class="case-question">${escapeHTML(r.question)}</span></td><td><span class="tag">${labels[r.difficulty]}</span></td>${metrics.map(([key])=>`<td class="${scoreClass(r[key])}">${fmt(r[key])}</td>`).join('')}<td><span class="overall-score ${scoreClass(r.overall)}">${fmt(r.overall)}</span></td><td><span class="status-label ${r.passed?'teal-text':'coral-text'}">${r.passed?'Passed':'Failed'}<small>${escapeHTML(r.failure_type||'—')}</small></span></td></tr>`).join('');$('result-count').textContent=`${rows.length} / ${results.length} câu hỏi`;$('empty-state').hidden=rows.length>0;}
['search','difficulty','status','sort'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',renderCases));
$('reset-filters').addEventListener('click',()=>{$('search').value='';$('difficulty').value='all';$('status').value='all';$('sort').value='id';renderCases()});renderCases();
const rr=data.reranking, avg=rr.averages;
$('rerank-stats').innerHTML=`<article class="stat-card"><span>Context Recall</span><strong>${fmt(avg.recall_before)} <span class="muted">/ ${fmt(avg.recall_after)}</span></strong><p>Trước / sau · Không đổi cả 20 cases</p></article><article class="stat-card"><span>Context Precision</span><strong>${fmt(avg.precision_before)} <span class="muted">/ ${fmt(avg.precision_after)}</span></strong><p class="coral-text">Delta ${avg.delta_precision.toFixed(4)} · Không cải thiện trung bình</p></article><article class="stat-card"><span>Phân bố thay đổi</span><strong><span class="teal-text">${rr.improved}</span> / ${rr.unchanged} / <span class="coral-text">${rr.worsened}</span></strong><p>Tăng / Không đổi / Giảm</p></article>`;
$('rerank-rows').innerHTML=rr.results.map(r=>`<tr><td><button class="case-id" data-case="${r.id}">${r.id}</button></td>${['recall_before','recall_after','precision_before','precision_after'].map(k=>`<td>${fmt(r[k])}</td>`).join('')}<td class="${r.delta_precision>0?'teal-text':r.delta_precision<0?'coral-text':'muted'}">${r.delta_precision>0?'+':''}${fmt(r.delta_precision)}</td><td class="muted">${r.original_ranks_after_rerank.join(' · ')}</td></tr>`).join('');
let currentCase=null;
function renderEvidence(mode){const golden=data.golden.qa_pairs.find(r=>r.id===currentCase),actual=data.actual.answers.find(r=>r.id===currentCase);const list=mode==='gold'?golden.contexts:actual.retrieved_contexts;$('evidence-list').innerHTML=list.map((c,i)=>`<details ${i===0?'open':''}><summary>${mode==='gold'?'Gold '+(i+1):'Hạng '+(i+1)+' · '+escapeHTML(c.chunk_id)}<small>${escapeHTML(c.source_doc)}</small></summary><p>${escapeHTML(c.text)}</p></details>`).join('');document.querySelectorAll('[data-evidence]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.evidence===mode)));}
function openCase(id){const r=results.find(r=>r.id===id);if(!r)return;currentCase=id;const gold=data.golden.qa_pairs.find(g=>g.id===id);$('detail-content').innerHTML=`<div class="detail-body"><div class="detail-heading"><h2 id="detail-title">${id}</h2><span class="tag">${labels[r.difficulty]}</span><span class="tag ${r.passed?'teal':'coral'}">${r.passed?'Passed':'Failed · '+escapeHTML(r.failure_type)}</span></div><p class="detail-question">${escapeHTML(r.question)}</p><div class="detail-scores">${[...metrics,['overall','Overall']].map(([key,label])=>`<div class="detail-score"><span>${label}</span><strong class="${scoreClass(r[key])}">${fmt(r[key])}</strong></div>`).join('')}</div><div class="answer-grid"><article class="answer-box"><h3>ACTUAL ANSWER <span class="muted">· gpt-4o-mini</span></h3><div class="answer-text">${escapeHTML(r.actual_answer)}</div></article><article class="answer-box"><h3>EXPECTED ANSWER <span class="muted">· Gold reference</span></h3><div class="answer-text">${escapeHTML(gold.expected_answer)}</div></article></div>${notes[id]?`<div class="review-note"><strong>Đọc từ trace</strong><br>${escapeHTML(notes[id])}</div>`:''}<h3 class="evidence-heading">Bằng chứng</h3><div class="evidence-tabs" role="tablist" aria-label="Loại evidence"><button type="button" role="tab" aria-selected="true" data-evidence="retrieved">Retrieved chunks</button><button type="button" role="tab" aria-selected="false" data-evidence="gold">Gold evidence</button></div><div id="evidence-list"></div><p class="footnote">Gold context dùng cho Faithfulness. Chunks theo hạng dùng cho Context Recall / Precision.</p></div>`;renderEvidence('retrieved');if(!$('case-dialog').open)$('case-dialog').showModal();$('case-dialog').scrollTop=0;}
document.addEventListener('click',event=>{const caseButton=event.target.closest('[data-case]');if(caseButton)openCase(caseButton.dataset.case);const evidenceButton=event.target.closest('[data-evidence]');if(evidenceButton)renderEvidence(evidenceButton.dataset.evidence)});
$('close-dialog').addEventListener('click',()=>$('case-dialog').close());
document.addEventListener('keydown',event=>{if(event.target.matches('[data-evidence]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const buttons=[...document.querySelectorAll('[data-evidence]')];const index=buttons.indexOf(event.target);const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;renderEvidence(buttons[next].dataset.evidence);buttons[next].focus();}});
$('case-dialog').addEventListener('click',event=>{if(event.target===$('case-dialog')){const box=$('case-dialog').getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)$('case-dialog').close()}});
